(239, 438, '31', 828, 14580, 'Sudah cukup baik, tapi mungkin untuk bahan materi yang diberikan bisa ditambahkan dari dosen yang mengampu juga, jadi tidak hanya dari ppt mahasiswa. 🙏🏻', 'teori', '2026-02-23 01:14:13', '2026-02-23 01:14:13'),
(240, 438, '31', 829, 14581, 'Sudah cukup baik, tapi mungkin dalam bahan materi nya bisa didapat dari dosen pengampu juga, jadi tidak hanya dari presentasi mahasiswa. 🙏🏻', 'teori', '2026-02-23 01:16:53', '2026-02-23 01:16:53'),
(241, 438, '13', 830, 14582, 'Sudah cukup baik. 🙏🏻', 'teori', '2026-02-23 01:18:31', '2026-02-23 01:18:31'),
(242, 438, '45', 831, 14583, 'Sudah cukup baik. 🙏🏻', 'teori', '2026-02-23 01:19:49', '2026-02-23 01:19:49'),
(243, 438, '36', 831, 14583, 'Sudah cukup baik. 🙏🏻', 'teori', '2026-02-23 01:21:55', '2026-02-23 01:21:55'),
(244, 438, '37', 832, 14584, 'Sudah cukup baik. 🙏🏻', 'teori', '2026-02-23 01:23:07', '2026-02-23 01:23:07'),
(245, 438, '35', 833, 14585, 'Sudah cukup baik, tapi mungkin pada saat praktikum, penjelasan/pembahasan diakhir praktikum bisa lebih detail dan dibahas. 🙏🏻', 'teori', '2026-02-23 01:25:14', '2026-02-23 01:25:14'),
(246, 438, '37', 833, 14585, 'Sudah cukup baik. 🙏🏻', 'teori', '2026-02-23 01:26:15', '2026-02-23 01:26:15'),
